130	    public void setAddressLine2(String addressLine2) {
131	        this.addressLine2 = addressLine2;
132	    }
133	
134	    public String getCity() {
135	        return this.city;
136	    }
137	
138	    public void setCity(String city) {
139	        this.city = city;
140	    }
141	
142	    public String getTelephone() {
143	        return this.telephone;
144	    }
145	
146	    public void setTelephone(String telephone) {
147	        this.telephone = telephone;
148	    }
149	
150	    public String getEmail() {
151	        return this.email;
152	    }
153	
154	    public void setEmail(String email) {
155	        this.email = email;
156	    }
157	
158	    public String getTitle() {
159	        return this.title;
160	    }
161	
162	    public void setTitle(String title) {
163	        this.title = title;
164	    }
165	
166	    /**
167	     * The owner's salutation for display: the {@link #title} followed by a single space
168	     * and the last name (e.g. {@code "DR Who"}), or just the last name when no title is
169	     * present. Derived from the owner's own fields.
170	     */
171	    @Transient
172	    public String getSalutation() {
173	        if (this.title == null || this.title.isBlank()) {
174	            return this.getLastName();
175	        }
176	        return this.title + " " + this.getLastName();
177	    }
178	
179	    public LocalDate getRegistrationDate() {
180	        return this.registrationDate;
181	    }
182	
183	    public void setRegistrationDate(LocalDate registrationDate) {
184	        this.registrationDate = registrationDate;
185	    }
186	
187	    public LocalDate getBirthDate() {
188	        return this.birthDate;
189	    }
190	
191	    public void setBirthDate(LocalDate birthDate) {
192	        this.birthDate = birthDate;
193	    }
194	
195	    /**
196	     * The owner's age band derived from {@link #birthDate}, computed against the
197	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} when
198	     * 18 to 64 inclusive, {@code "SENIOR"} when 65 or over. Null when either the birth
199	     * date or the registration date is absent.
200	     */
201	    @Transient
202	    public String getAgeBand() {
203	        if (this.birthDate == null || this.registrationDate == null) {
204	            return null;
205	        }
206	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
207	        if (age < 18) {
208	            return "MINOR";
209	        }
210	        if (age < 65) {
211	            return "ADULT";
212	        }
213	        return "SENIOR";
214	    }
215	
216	    public String getCustomerCode() {
217	        return this.customerCode;
218	    }
219	
220	    public void setCustomerCode(String customerCode) {
221	        this.customerCode = customerCode;
222	    }
223	
224	    /**
225	     * The owner's current primary identifier. This is the {@link #getCustomerCode()
226	     * customerCode} today; when the customerCode is later unified into the memberId,
227	     * this becomes the memberId. It is the single source of truth for "the identifier
228	     * that identifies this owner", so downstream consumers (such as the audit event)
229	     * follow the switch automatically.
230	     */
231	    @Transient
232	    public String getPrimaryIdentifier() {
233	        return this.customerCode;
234	    }
235	
236	    public String getHouseholdId() {
237	        return this.householdId;
238	    }
239	
240	    public void setHouseholdId(String householdId) {
241	        this.householdId = householdId;
242	    }
