294	    }
295	
296	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
297	        this.possibleDuplicate = possibleDuplicate;
298	    }
299	
300	    public Integer getPossibleDuplicateOf() {
301	        return this.possibleDuplicateOf;
302	    }
303	
304	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
305	        this.possibleDuplicateOf = possibleDuplicateOf;
306	    }
307	
308	    public Boolean getDeleted() {
309	        return this.deleted;
310	    }
311	
312	    public void setDeleted(Boolean deleted) {
313	        this.deleted = deleted;
314	    }
315	
316	    /**
317	     * The owner's name formatted for display as {@code "LastName, FirstName"}.
318	     */
319	    @Transient
320	    public String getDisplayName() {
321	        return this.getLastName() + ", " + this.getFirstName();
322	    }
323	
324	    /**
325	     * The owner's initials: the upper-cased first letters of firstName and
326	     * lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
327	     */
328	    @Transient
329	    public String getInitials() {
330	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
331	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
332	    }
333	
334	    /**
335	     * The fiscal year (starting 1 July) that the registration date falls in, as a
336	     * number: a date on or after 1 July belongs to the fiscal year of its own calendar
337	     * year, an earlier date belongs to the previous calendar year's fiscal year. Single
338	     * source of truth for the fiscal year, so {@link #getFiscalYear()}, the
339	     * {@link #getMembershipNumber() membership number} year segment and the tenure count
340	     * in {@link #getMembershipPoints()} cannot drift apart.
341	     */
342	    private static int fiscalYearOf(LocalDate date) {
343	        int year = date.getYear();
344	        return date.getMonthValue() >= Month.JULY.getValue() ? year : year - 1;
345	    }
346	
347	    /**
348	     * The owner's fiscal year, formatted {@code "FY<YY>"} where YY is the last two
349	     * digits of the fiscal year (starting 1 July) of the business-day-adjusted
350	     * {@link #registrationDate} (e.g. {@code "FY26"} for a date in July 2026 to
351	     * June 2027). Derived from the owner's own fields; null when the registration date
352	     * is absent.
353	     */
354	    @Transient
355	    public String getFiscalYear() {
356	        if (this.registrationDate == null) {
357	            return null;
358	        }
359	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
360	    }
361	
362	    /**
363	     * The owner's membership number, formatted {@code "<customerCode>-M<YY>"} where
364	     * YY is the last two digits of the registration date's fiscal year (starting
365	     * 1 July; e.g. {@code "NSW-A1B2C3D4-M26"} for a date in July 2026 to June 2027).
366	     * Derived from the owner's own fields; null when either the customer code or
367	     * registration date is absent.
368	     */
369	    @Transient
370	    public String getMembershipNumber() {
371	        if (this.customerCode == null || this.registrationDate == null) {
372	            return null;
373	        }
374	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
375	    }
376	
377	    /**
378	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
379	     * contained in the {@code customerCode}, scanning right to left and doubling the
380	     * rightmost digit first; non-digit characters are ignored. Derived from the owner's
381	     * own fields; null when the customer code is absent.
382	     */
383	    @Transient
384	    public Integer getCheckDigit() {
385	        if (this.customerCode == null) {
386	            return null;
387	        }
388	        int sum = 0;
389	        boolean dbl = true;
390	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
391	            char c = this.customerCode.charAt(i);
392	            if (c < '0' || c > '9') {
393	                continue;
394	            }
395	            int d = c - '0';
396	            if (dbl) {
397	                d *= 2;
398	                if (d > 9) {
399	                    d -= 9;
400	                }
401	            }
402	            sum += d;
403	            dbl = !dbl;
404	        }
405	        return (10 - (sum % 10)) % 10;
406	    }
407	
408	    /**
409	     * The owner's membership points: a running score built from the owner's own fields.
410	     * Starts at 0 and gains 2 when an email address is present, a further 1 when the owner
411	     * has no namesakes ({@code namesakeCount} is 0), a further 2 when it belongs to a
412	     * household of 3 or more members ({@code householdSize} is 3 or more), and a further 3
413	     * for tenure of more than one elapsed fiscal year (the fiscal years, starting 1 July,
414	     * from {@link #registrationDate} to the current date). A newly created owner has zero
415	     * tenure, so the pre-tenure factors alone top out at 5 points. Derived from the owner's
416	     * own fields.
417	     */
418	    @Transient
419	    public Integer getMembershipPoints() {
420	        int points = 0;
421	        boolean hasEmail = this.email != null && !this.email.isBlank();
422	        if (hasEmail) {
423	            points += 2;
424	        }
425	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
426	        if (unique) {
427	            points += 1;
428	        }
429	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
430	        if (largeHousehold) {
431	            points += 2;
432	        }
433	        boolean tenured = this.registrationDate != null
434	            && (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate)) > 1;
435	        if (tenured) {
436	            points += 3;
437	        }
438	        return points;
439	    }
440	
441	    /**
442	     * The owner's membership level: a number from 1 to 4 derived by banding
443	     * {@link #getMembershipPoints()} — 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6
444	     * or more. Derived from the owner's own fields, then capped by
445	     * {@link #membershipLevelCap} when set: a new owner's level cannot exceed one above the
446	     * current maximum level among their household members. With no existing household member
447	     * the cap is absent and the banded value stands.
448	     */
449	    @Transient
450	    public Integer getMembershipLevel() {
451	        int level = bandMembershipLevel(getMembershipPoints());
452	        if (this.membershipLevelCap != null && this.membershipLevelCap < level) {
453	            return this.membershipLevelCap;
454	        }
455	        return level;
456	    }
457	
458	    private static int bandMembershipLevel(int points) {
459	        if (points <= 1) {
460	            return 1;
461	        }
462	        if (points <= 3) {
463	            return 2;
464	        }
465	        if (points <= 5) {
466	            return 3;
467	        }
468	        return 4;
469	    }
470	
471	    /**
472	     * Fixed city-to-region lookup table. Any city not listed derives locality
473	     * {@code "UNKNOWN"}.
474	     */
475	    private static final Map<String, String> CITY_REGION = Map.of(
476	        "Sydney", "NSW",
477	        "Melbourne", "VIC",
478	        "Brisbane", "QLD");
479	
480	    /**
481	     * Region -> inclusive 4-digit postcode range {low, high}: NSW 2000-2099,
482	     * VIC 3000-3099, QLD 4000-4099. The single source of truth for the
483	     * postcode-to-region mapping, consulted by {@link #regionForPostcode(String)}
484	     * (used by locality derivation) and {@link #hasPostcodeRange(String)} (used by
485	     * postcode validation).
486	     */
487	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
488	        "NSW", new int[] {2000, 2099},
489	        "VIC", new int[] {3000, 3099},
490	        "QLD", new int[] {4000, 4099});
491	
492	    /**
493	     * Fixed region-to-timezone lookup table, mapping each region to its IANA timezone
494	     * name: NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane.
495	     * Any region not listed (including {@code "UNKNOWN"}) has no timezone.
496	     */
497	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
498	        "NSW", "Australia/Sydney",
499	        "VIC", "Australia/Melbourne",
500	        "QLD", "Australia/Brisbane");
501	
502	    /**
503	     * The owner's locality: the REGION component of the owner's region-and-hash identity.
504	     * Read off the {@code customerCode} prefix (the part before the first {@code '-'}) when
505	     * a customer code is present, otherwise derived straight from the postcode via
506	     * {@link #identityRegion(String)}. Either way this yields the region the customer code
507	     * was built from — NSW/VIC/QLD, or {@code "UNKNOWN"} when the postcode is absent or in
508	     * no known range. Derived from the owner's own fields.
509	     */
510	    @Transient
511	    public String getLocality() {
512	        if (this.customerCode != null) {
513	            int dash = this.customerCode.indexOf('-');
514	            if (dash > 0) {
515	                return this.customerCode.substring(0, dash);
516	            }
517	        }
518	        return identityRegion(this.postcode);
519	    }
520	
521	    /**
522	     * The REGION component of an owner's region-and-hash identity: the region derived from
523	     * the postcode via {@link #regionForPostcode(String)} (NSW/VIC/QLD), or
524	     * {@code "UNKNOWN"} when the postcode is absent or in no known range. The single source
525	     * of truth for the identity's region, so the {@code customerCode} prefix and the
526	     * {@link #getLocality() locality} cannot drift apart.
527	     */
528	    public static String identityRegion(String postcode) {
529	        String region = regionForPostcode(postcode);
530	        return region != null ? region : "UNKNOWN";
531	    }
532	
533	    /**
534	     * Whether {@code region} is a known region (NSW, VIC or QLD) rather than the
535	     * {@code "UNKNOWN"} sentinel that {@link #identityRegion(String)} yields for a postcode
536	     * in no known range. The single source of truth for "is this a real region?",
537	     * independent of the postcode-range and timezone tables; used by
538	     * {@link #getOwnerSegment() owner segmentation} to decide METRO vs REGIONAL.
539	     */
540	    public static boolean isKnownRegion(String region) {
541	        return !"UNKNOWN".equals(region);
542	    }
543	
544	    /**
545	     * The canonical region for a city per the fixed city-to-region table
546	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or
547	     * {@code "UNKNOWN"} when the city is not in the table. The single source of truth
548	     * for the city-to-region mapping, used as the city's region in postcode validation.
549	     */
550	    public static String regionForCity(String city) {
551	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
552	    }
553	
554	    /**
555	     * The canonical region for a 4-digit postcode per the fixed range table
556	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the postcode
557	     * is absent, not a well-formed integer, or in no known range. Reads the shared
558	     * {@link #REGION_POSTCODE_RANGES} table; used by {@link #identityRegion(String)}
559	     * for the identity's region and by postcode validation to range-check a submitted
560	     * postcode against its city's region.
561	     */
562	    public static String regionForPostcode(String postcode) {
563	        if (postcode == null) {
564	            return null;
565	        }
566	        int value;
567	        try {
568	            value = Integer.parseInt(postcode.trim());
569	        } catch (NumberFormatException ex) {
570	            return null;
571	        }
572	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
573	            int[] range = entry.getValue();
574	            if (value >= range[0] && value <= range[1]) {
575	                return entry.getKey();
576	            }
577	        }
578	        return null;
579	    }
580	
581	    /**
582	     * Whether the region is subject to postcode range validation, i.e. has a known
583	     * range in the shared {@link #REGION_POSTCODE_RANGES} table. A region with no range
584	     * (including {@code "UNKNOWN"}) accepts any well-formed postcode.
585	     */
586	    public static boolean hasPostcodeRange(String region) {
587	        return REGION_POSTCODE_RANGES.containsKey(region);
588	    }
589	
590	    /**
591	     * The owner's IANA timezone, derived from the owner's {@link #getLocality() locality}
592	     * (its region) via the fixed region-to-timezone table ({@code NSW->Australia/Sydney},
593	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}). Null when the
594	     * region is not one of these (e.g. {@code "UNKNOWN"}). Derived from the owner's own
595	     * fields.
596	     */
597	    @Transient
598	    public String getTimezone() {
599	        return REGION_TIMEZONE.get(getLocality());
600	    }
601	
602	    /**
603	     * The owner's segment, formatted {@code "<TIER>_<AREA>"} — one of
604	     * {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or
605	     * {@code "STANDARD_REGIONAL"}. TIER is {@code "PREMIUM"} when
606	     * {@link #getMembershipLevel() membershipLevel} is 3 or more, otherwise
607	     * {@code "STANDARD"}. AREA is {@code "METRO"} when the {@link #getLocality() locality}
608	     * is a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}. Derived from the
609	     * owner's own fields.
610	     */
611	    @Transient
612	    public String getOwnerSegment() {
613	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
614	        String area = isKnownRegion(getLocality()) ? "METRO" : "REGIONAL";
615	        return tier + "_" + area;
616	    }
617	
618	    /**
619	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
620	     * present, otherwise {@code "PHONE"}. Derived from the owner's own fields.
621	     */
622	    @Transient
623	    public String getContactPreference() {
624	        boolean hasEmail = this.email != null && !this.email.isBlank();
625	        return hasEmail ? "EMAIL" : "PHONE";
626	    }
627	
628	    /**
629	     * The owner's identity key: the lower-case hex SHA-256 of
630	     * {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}. The
631	     * telephone is already stored in E.164 form, the email is lower-cased (an empty segment
632	     * when absent), and the last name is reduced to its {@link #soundex(String) Soundex}
633	     * code. This is the single identity used for duplicate detection: two owners with the
634	     * same key are the same person (a 409 on create); an owner whose key differs but whose
635	     * Soundex last name and postcode match an existing owner is a soft match instead.
636	     * Derived from the owner's own fields.
637	     */
638	    @Transient
639	    public String getIdentityKey() {
640	        String normalizedTelephone = keyPart(this.telephone);
641	        String lowerEmail = keyPart(this.email == null ? null : this.email.toLowerCase(Locale.ROOT));
642	        String soundexLastName = soundex(this.getLastName());
643	        return sha256Hex(normalizedTelephone + "|" + lowerEmail + "|" + soundexLastName);
644	    }
645	
646	    private static String keyPart(String value) {
647	        return (value == null || value.isBlank()) ? "" : value;
648	    }
649	
650	    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
651	    private static String sha256Hex(String value) {
652	        try {
653	            byte[] digest = MessageDigest.getInstance("SHA-256")
654	                .digest(value.getBytes(StandardCharsets.UTF_8));
655	            StringBuilder sb = new StringBuilder(digest.length * 2);
656	            for (byte b : digest) {
657	                sb.append(String.format("%02x", b));
658	            }
659	            return sb.toString();
660	        }
661	        catch (NoSuchAlgorithmException ex) {
662	            throw new IllegalStateException("SHA-256 not available", ex);
663	        }
664	    }
665	
666	    /**
667	     * The American Soundex code of {@code name}: the upper-cased first letter followed by
668	     * three digits that encode the remaining consonants. Vowels and {@code H}/{@code W} are
669	     * not coded; adjacent letters with the same code collapse to one, as do two same-coded
670	     * letters separated only by {@code H} or {@code W}. The code is right-padded with zeros
671	     * and truncated to four characters. An absent or letter-free name yields the empty
672	     * string. The single source of truth for an owner's last-name phonetic key, used by the
673	     * {@link #getIdentityKey() identity key} and by soft-duplicate matching. It lives here
674	     * (rather than beside the exact-match name normalization in the package-private
675	     * {@code OwnerNames} helper) because {@code getIdentityKey()} is an entity-level derived
676	     * getter and must not depend on the request-function layer; the two are distinct name
677	     * concerns — exact comparison vs. phonetic keying — not a duplicated utility.
678	     */
679	    public static String soundex(String name) {
680	        if (name == null) {
681	            return "";
682	        }
683	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
684	        if (letters.isEmpty()) {
685	            return "";
686	        }
687	        StringBuilder code = new StringBuilder();
688	        code.append(letters.charAt(0));
689	        char prev = soundexDigit(letters.charAt(0));
690	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
691	            char c = letters.charAt(i);
692	            char digit = soundexDigit(c);
693	            if (digit != '0' && digit != prev) {
694	                code.append(digit);
695	            }
696	            // Vowels reset the previous code so same-coded consonants either side are coded
697	            // twice; H and W do not, so same-coded letters they separate still collapse.
698	            if (c != 'H' && c != 'W') {
699	                prev = digit;
700	            }
701	        }
702	        while (code.length() < 4) {
703	            code.append('0');
704	        }
705	        return code.toString();
706	    }
707	
708	    private static char soundexDigit(char c) {
709	        switch (c) {
710	            case 'B': case 'F': case 'P': case 'V':
711	                return '1';
712	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
713	                return '2';
714	            case 'D': case 'T':
715	                return '3';
716	            case 'L':
717	                return '4';
718	            case 'M': case 'N':
719	                return '5';
720	            case 'R':
721	                return '6';
722	            default:
723	                return '0';
724	        }
725	    }
726	
727	    /**
728	     * The stored E.164 {@link #telephone} formatted for humans: the country code,
729	     * a space, then the national digits grouped in threes (e.g.
730	     * {@code "+61 412 345 678"}). The {@code '+'} and country code are taken from the
731	     * E.164 value (a {@code '+1'} NANP country code is a single digit, any other is
732	     * treated as two digits, matching the recognized {@code '+61'}/{@code '+1'} forms),
733	     * and the national digits follow in space-separated groups of three. Returns the raw
734	     * value unchanged when it is absent or not a {@code '+'}-prefixed run of digits.
735	     * Derived from the owner's own fields; the raw {@link #telephone} stays E.164.
736	     */
737	    @Transient
738	    public String getTelephoneDisplay() {
739	        if (this.telephone == null || !this.telephone.startsWith("+")) {
740	            return this.telephone;
741	        }
742	        String digits = this.telephone.substring(1);
743	        if (!digits.matches("\\d+")) {
744	            return this.telephone;
745	        }
746	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
747	        if (digits.length() <= countryCodeLength) {
748	            return this.telephone;
749	        }
750	        String countryCode = digits.substring(0, countryCodeLength);
751	        String national = digits.substring(countryCodeLength);
752	        StringBuilder grouped = new StringBuilder();
753	        for (int i = 0; i < national.length(); i += 3) {
754	            if (grouped.length() > 0) {
755	                grouped.append(' ');
756	            }
757	            grouped.append(national, i, Math.min(i + 3, national.length()));
758	        }
759	        return "+" + countryCode + " " + grouped;
760	    }
761	
762	    protected Set<Pet> getPetsInternal() {
763	        if (this.pets == null) {
764	            this.pets = new HashSet<>();
765	        }
766	        return this.pets;
767	    }
768	
769	    protected void setPetsInternal(Set<Pet> pets) {
770	        this.pets = pets;
771	    }
772	
773	    public List<Pet> getPets() {
774	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
775	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
776	        return Collections.unmodifiableList(sortedPets);
777	    }
778	
779	    public void setPets(List<Pet> pets) {
780	        this.pets = new HashSet<>(pets);
781	    }
782	
783	    public void addPet(Pet pet) {
784	        getPetsInternal().add(pet);
785	        pet.setOwner(this);
786	    }
787	
788	    /**
789	     * Return the Pet with the given name, or null if none found for this Owner.
790	     *
791	     * @param name to test
792	     * @return true if pet name is already in use
793	     */
794	    public Pet getPet(String name) {
795	        return getPet(name, false);
796	    }
797	
798	    /**
799	     * Return the Pet with the given name, or null if none found for this Owner.
800	     *
801	     * @param name to test
802	     * @return true if pet name is already in use
803	     */
804	    public Pet getPet(String name, boolean ignoreNew) {
805	        name = name.toLowerCase();
806	        for (Pet pet : getPetsInternal()) {
807	            if (!ignoreNew || !pet.isNew()) {
808	                String compName = pet.getName();
809	                compName = compName.toLowerCase();
810	                if (compName.equals(name)) {
811	                    return pet;
812	                }
813	            }
814	        }
815	        return null;
816	    }
817	
818	    public Pet getPet(Integer petId) {
819	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
820	    }
821	
822	    @Override
823	    public String toString() {
824	        return new ToStringCreator(this)
825	
826	            .append("id", this.getId())
827	            .append("new", this.isNew())
828	            .append("lastName", this.getLastName())
829	            .append("firstName", this.getFirstName())
830	            .append("address", this.address)
831	            .append("city", this.city)
832	            .append("telephone", this.telephone)
833	            .append("email", this.email)
834	            .toString();
835	    }
836	}
